format-code-task-001980.build_env_cmd:
#!/bin/bash
cd /testbed

# Ensure Python 2.7 is active (pyenv is configured in .bashrc)
export PATH="$HOME/.pyenv/bin:$PATH"
eval "$(pyenv init -)"
eval "$(pyenv virtualenv-init -)"
pyenv global 2.7.18

# Stop PG 16 if it is running on port 5432
pg_ctlcluster 16 main stop 2>/dev/null || true

# Start PG 9.6 on port 5432 if not already running
if ! /usr/local/pg96/bin/pg_isready -h localhost -p 5432 -q 2>/dev/null; then
    sudo -u postgres /usr/local/pg96/bin/pg_ctl -D /var/lib/postgresql/9.6/main -l /var/lib/postgresql/9.6/logfile start
    sleep 2
fi

# Create commonconfig.py for the test database connection
cp /testbed/socorro/unittest/config/commonconfig.py.dist /testbed/socorro/unittest/config/commonconfig.py

# Ensure citext extension exists
sudo -u postgres /usr/local/pg96/bin/psql -h localhost -d socorro_integration_test -c "CREATE EXTENSION IF NOT EXISTS citext;" 2>/dev/null || true

# Recreate the database to start fresh
sudo -u postgres /usr/local/pg96/bin/psql -h localhost <<'SQL'
DROP DATABASE IF EXISTS socorro_integration_test;
CREATE DATABASE socorro_integration_test OWNER breakpad_rw;
SQL

# Load schema and add is_gc_count column
sudo -u postgres /usr/local/pg96/bin/psql -h localhost -d socorro_integration_test -c "CREATE EXTENSION IF NOT EXISTS citext;"
sudo -u postgres /usr/local/pg96/bin/psql -h localhost -d socorro_integration_test -v ON_ERROR_STOP=0 -f /testbed/sql/schema.sql >/dev/null 2>&1
sudo -u postgres /usr/local/pg96/bin/psql -h localhost -d socorro_integration_test <<'SQL'
ALTER TABLE tcbs ADD COLUMN IF NOT EXISTS is_gc_count integer NOT NULL DEFAULT 0;
ALTER TABLE tcbs_build ADD COLUMN IF NOT EXISTS is_gc_count integer NOT NULL DEFAULT 0;
GRANT ALL PRIVILEGES ON ALL TABLES IN SCHEMA public TO breakpad_rw;
GRANT ALL PRIVILEGES ON ALL SEQUENCES IN SCHEMA public TO breakpad_rw;
GRANT ALL PRIVILEGES ON ALL FUNCTIONS IN SCHEMA public TO breakpad_rw;
GRANT USAGE ON SCHEMA public TO breakpad_rw;
GRANT ALL PRIVILEGES ON ALL TABLES IN SCHEMA public TO test;
GRANT ALL PRIVILEGES ON ALL SEQUENCES IN SCHEMA public TO test;
GRANT ALL PRIVILEGES ON ALL FUNCTIONS IN SCHEMA public TO test;
SQL

# Run the target test
PYTHONPATH=/testbed python -m nose socorro/unittest/external/postgresql/test_crashes_signatures.py -v

